<?php
declare(strict_types=1);
session_start();
require_once __DIR__ . '/config/database.php';
require_once __DIR__ . '/config/audit.php';
if (!isset($_SESSION['user'])) { header('Location: login.php'); exit; }
$me=$_SESSION['user'];
if (($me['role_code']??'')!=='ADMIN') { http_response_code(403); exit('ไม่มีสิทธิ์เข้าถึงหน้านี้'); }
audit_log($pdo,$me,'page_view','admin_logs.php');

$eventNames=[
    'page_view'=>'เปิดหน้าเว็บไซต์','login_success'=>'เข้าสู่ระบบสำเร็จ','login_failed'=>'เข้าสู่ระบบไม่สำเร็จ',
    'login_blocked'=>'บัญชีถูกระงับการเข้าสู่ระบบ','login_csrf_failed'=>'คำขอเข้าสู่ระบบไม่ถูกต้อง','logout'=>'ออกจากระบบ',
    'task_created'=>'สร้างงาน','task_updated'=>'แก้ไขงาน','task_status_changed'=>'เปลี่ยนสถานะงาน',
    'user_created'=>'สร้างบัญชีผู้ใช้','user_updated'=>'แก้ไขบัญชีผู้ใช้','user_status_changed'=>'เปลี่ยนสถานะบัญชี',
    'department_created'=>'เพิ่มหน่วยงาน','document_downloaded'=>'ดาวน์โหลดเอกสาร','password_changed'=>'เปลี่ยนรหัสผ่าน',
];
$event=trim((string)($_GET['event']??'')); $query=trim((string)($_GET['q']??''));
$from=trim((string)($_GET['from']??'')); $to=trim((string)($_GET['to']??''));
$page=max(1,(int)($_GET['page']??1)); $limit=50; $where=[]; $params=[];
if (isset($eventNames[$event])) { $where[]='event_type=?'; $params[]=$event; }
if ($query!=='') { $where[]='(username LIKE ? OR page_path LIKE ? OR ip_address LIKE ?)'; $needle='%'.$query.'%'; array_push($params,$needle,$needle,$needle); }
foreach (['from'=>'>=','to'=>'<='] as $key=>$operator) {
    $value=${$key}; $date=DateTime::createFromFormat('!Y-m-d',$value);
    if ($value!=='' && $date && $date->format('Y-m-d')===$value) { $where[]='DATE(created_at) '.$operator.' ?'; $params[]=$value; }
}
$whereSql=$where?' WHERE '.implode(' AND ',$where):'';
$countStmt=$pdo->prepare('SELECT COUNT(*) FROM audit_logs'.$whereSql); $countStmt->execute($params); $total=(int)$countStmt->fetchColumn();
$pages=max(1,(int)ceil($total/$limit)); $page=min($page,$pages); $offset=($page-1)*$limit;
$stmt=$pdo->prepare('SELECT log_id,user_id,username,event_type,page_path,ip_address,user_agent,details,created_at FROM audit_logs'.$whereSql.' ORDER BY created_at DESC,log_id DESC LIMIT '.$limit.' OFFSET '.$offset);
$stmt->execute($params); $logs=$stmt->fetchAll();
function logEsc(?string $s):string{return htmlspecialchars($s??'',ENT_QUOTES,'UTF-8');}
function logQuery(array $overrides=[]):string{return '?'.http_build_query(array_merge($_GET,$overrides));}
?>
