 11px Prompt,sans-serif;cursor:pointer;white-space:nowrap}.btn.light{background:#f1f0ec;color:#484a4d}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:900px}th,td{text-align:left;padding:10px 9px;border-bottom:1px solid #efeee9;vertical-align:top;font-size:11px}th{background:#fbfaf8;color:#666a6e;font-weight:500;white-space:nowrap}.badge{display:inline-block;background:#fff0e3;color:#a95112;border-radius:20px;padding:4px 8px;white-space:nowrap;font-size:10px}.meta{color:var(--muted);font-size:10px;max-width:350px;overflow-wrap:anywhere}.empty{text-align:center;padding:36px;color:#999}.pager{display:flex;justify-content:space-between;align-items:center;padding:12px 15px;font-size:11px;color:var(--muted)}.pager a{color:#b95b17;text-decoration:none}.hint{color:var(--muted);font-size:10px;margin:0}
