<section class="panel"><div class="panel-h"><h2>ค้นหาประวัติ</h2><span class="badge">ทั้งหมด <?=number_format($total)?> รายการ</span></div><div class="panel-body"><form class="filters" method="get"><div><label>ผู้ใช้ / หน้าเว็บ / IP</label><input type="search" name="q" value="<?=logEsc($query)?>" placeholder="ค้นหา"></div><div><label>กิจกรรม</label><select name="event"><option value="">ทุกกิจกรรม</option><?php foreach($eventNames as $key=>$label):?><option value="<?=logEsc($key)?>" <?=$event===$key?'selected':''?>><?=logEsc($label)?></option><?php endforeach;?></select></div><div><label>ตั้งแต่วันที่</label><input type="date" name="from" value="<?=logEsc($from)?>"></div><div><label>ถึงวันที่</label><input type="date" name="to" value="<?=logEsc($to)?>"></div><button class="btn">กรอง</button><a class="btn light" href="admin_logs.php">ล้าง</a></form></div></section>
<section class="panel"><div class="panel-h"><h2>รายการล่าสุด</h2><p class="hint">แสดง <?=count($logs)?> รายการต่อหน้า · เรียงจากใหม่ไปเก่า</p></div><div class="table-wrap"><table><thead><tr><th>วันและเวลา</th><th>ผู้ใช้</th><th>กิจกรรม</th><th>หน้า</th><th>IP Address</th><th>เบราว์เซอร์</th><th>รายละเอียด</th></tr></thead><tbody><?php if(!$logs):?><tr><td colspan="7" class="empty">ยังไม่มีประวัติที่ตรงกับเงื่อนไข</td></tr><?php else:foreach($logs as $log):$details=json_decode((string)$log['details'],true)?:[];$summary=[];foreach($details as $key=>$value){$summary[]=$key.': '.(is_scalar($value)?(string)$value:'');}?><tr><td><?=logEsc(date('d/m/Y H:i:s',strtotime($log['created_at'])))?></td><td><?=logEsc($log['username']??'ผู้ไม่เข้าสู่ระบบ')?><?php if($log['user_id']):?><br><span class="meta">ID <?=logEsc((string)$log['user_id'])?></span><?php endif;?></td><td><span class="badge"><?=logEsc($eventNames[$log['event_type']]??$log['event_type'])?></span></td><td><?=logEsc($log['page_path'])?></td><td><?=logEsc($log['ip_address']??'—')?></td><td><span class="meta" title="<?=logEsc($log['user_agent']??'')?>"><?=logEsc(mb_strimwidth((string)($log['user_agent']??'—'),0,75,'…','UTF-8'))?></span></td><td><?=logEsc(implode(' · ',$summary)?:'—')?></td></tr><?php endforeach;endif;?></tbody></table></div><div class="pager"><span>หน้า <?=$page?> / <?=$pages?></span><span><?php if($page>1):?><a href="<?=logEsc(logQuery(['page'=>$page-1]))?>">← ก่อนหน้า</a><?php endif;?><?php if($page<$pages):?><a style="margin-left:14px" href="<?=logEsc(logQuery(['page'=>$page+1]))?>">หน้าถัดไป →</a><?php endif;?></span></div></section><p class="hint" style="text-align:center">ประวัตินี้เข้าถึงได้เฉพาะผู้ดูแลระบบ</p></div></main></div></body></html>
